/**
 * Triggers the loan origination workflow for a specific client, identified by their company ID. This endpoint should be used to start the origination process for a new business loan.
 * @summary Initiate loan origination for a client company with given ID
 */
export const launchLoanOrigination = async (launchLoanOriginationRequestBody: LaunchLoanOriginationRequestBody, options?: RequestInit): Promise<launchLoanOriginationResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
const res = await fetch(getLaunchLoanOriginationUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(launchLoanOriginationRequestBody)
  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: launchLoanOriginationResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as launchLoanOriginationResponse
}



