export const getGetDocumentContentUrl = (applicationId: string,
    documentId: string,
    params?: GetDocumentContentParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/loans/applications/${applicationId}/documents/${documentId}?${stringifiedParams}` : `/loans/applications/${applicationId}/documents/${documentId}`
}

